CREATE TABLE IF NOT EXISTS ss03_pilot_review (canonical_id TEXT NOT NULL REFERENCES ss03_canonical(canonical_id),company_id INTEGER NOT NULL REFERENCES companies(company_id), decision TEXT NOT NULL,review_json TEXT NOT NULL, PRIMARY KEY(canonical_id,company_id));
CREATE TABLE IF NOT EXISTS ss03_pilot_basket (canonical_id TEXT NOT NULL REFERENCES ss03_canonical(canonical_id),quarter TEXT NOT NULL,cutoff TEXT NOT NULL,status TEXT NOT NULL,chart_ready INTEGER NOT NULL CHECK(chart_ready=0),PRIMARY KEY(canonical_id,quarter));
CREATE TABLE IF NOT EXISTS ss03_pilot_member (canonical_id TEXT NOT NULL,quarter TEXT NOT NULL,company_id INTEGER NOT NULL,eligibility TEXT NOT NULL,PRIMARY KEY(canonical_id,quarter,company_id),FOREIGN KEY(canonical_id,quarter) REFERENCES ss03_pilot_basket(canonical_id,quarter),FOREIGN KEY(canonical_id,company_id) REFERENCES ss03_pilot_review(canonical_id,company_id));
